 return `<section class="account-month-table-wrap"><p class="chart-ledger-note">${esc(monthName(k))} · ${esc(chartSeriesLabel(person))}. Crédits et débits reprennent les mouvements pris en compte, classés par date ; le solde réel enregistré ancre le calcul et les échéances passées non réglées sont reportées à demain. Les lignes « dette restante » non payées n’affectent pas le solde.</p><div class="account-month-table-scroll"><table class="account-month-table"><thead><tr><th>Libellé</th><th>Payé / reçu le</th><th>Crédit</th><th>Débit</th><th>Solde du compte</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="chart-ledger-empty">Aucun mouvement ce mois-ci.</td></tr>'}</tbody><tfoot><tr><th colspan="4">Solde final · ${esc(chartSeriesLabel(person))}</th><td class="money-balance">${eur(finalBalance)}</td></tr></tfoot></table></div></section>`;
