function monthOperationAction(e){if(e.type==='real-balance')return 'delete-balance';if(e.type==='balance-adjustment')return e.derived?'calculated':'delete-adjustment';if(e.type==='income')return 'delete-income';if(e.type==='expense'){if(String(e.sub||'').startsWith('remaining:')||String(e.sub||'').startsWith('parts-due:'))return 'calculated';return 'expense-payment'}if(e.type==='refund')return e.sourceId?'delete-refund':'calculated';if(e.type==='settlement')return data.accountSettlementDates?.[monthKey]?'clear-settlement':'calculated';return 'calculated'}
